#!/usr/bin/env bash

HOST="`hostname | sed -e 's/\([a-zA-Z0-9\-]*\).*/\1/'`"
USER="`whoami`"
HIM="$USER@$HOST"
WHEN="`date | awk '{
    if (NF==6) { print $1 " "  $2 " " $3 " "  $6 " at " $4 " " $5 }
    else       { print $1 " "  $2 " " $3 " " $7 " at " $4 " " $5 " " $6 }
}'`"

cat >version.c <<!END!
/**
 * Copyright (C) 2015-2026 unfacd works
 *
 * AUTO-GENERATED by version.c.sh — do not edit.
 *
 * Compiled: $WHEN
 * By:        $HIM
 */

#include <ufsrvscriptlib/ufsrvscriptlib_version.h>

#define STRINGISE_NX(A) #A
#define STRINGISE(A) STRINGISE_NX(A)

static const char *t_compiled  = "$WHEN";
static const char *u_compiled  = "$HIM";
static const char *ufsrvscriptlib_version =
    STRINGISE(UFSRVSCRIPTLIB_MAJOR) "."
    STRINGISE(UFSRVSCRIPTLIB_MINOR) "."
    STRINGISE(UFSRVSCRIPTLIB_PATCH);

const char *UfsrvScriptVersion(void)      { return ufsrvscriptlib_version; }
const char *UfsrvScriptVersionMajor(void) { return STRINGISE(UFSRVSCRIPTLIB_MAJOR); }
const char *UfsrvScriptVersionMinor(void) { return STRINGISE(UFSRVSCRIPTLIB_MINOR); }
const char *UfsrvScriptVersionPatch(void) { return STRINGISE(UFSRVSCRIPTLIB_PATCH); }
const char *UfsrvScriptCompiledTimestamp(void) { return t_compiled; }
const char *UfsrvScriptCompiledBy(void)        { return u_compiled; }
!END!
